package cn.sixnine.filmlog;

import android.app.PendingIntent;
import android.appwidget.*;
import android.content.*;
import android.widget.RemoteViews;

/** Launcher entry only; opening it never writes an exposure. */
public final class ExposureWidget extends AppWidgetProvider {
    static final String PREFS="exposure-widgets", CLASSIC="classic", FROST="frost";
    static String style(Context context,int id){return FROST.equals(Workspace.root(context).getSharedPreferences(PREFS,0).getString(id+".style",CLASSIC))?FROST:CLASSIC;}
    static boolean available(LogStore.Roll roll){return RecordRules.canRecord(roll.archived,roll.state);}
    static String target(Context context,int id){SharedPreferences prefs=Workspace.root(context).getSharedPreferences(PREFS,0);String workspace=prefs.getString(id+".workspace","");return workspace.equals(Workspace.current(context))?prefs.getString(id+".roll",""):"";}
    static boolean owned(Context context,int id){AppWidgetProviderInfo info=AppWidgetManager.getInstance(context).getAppWidgetInfo(id);return info!=null&&new ComponentName(context,ExposureWidget.class).equals(info.provider);}
    static void bind(Context context,int id,String roll){bind(context,id,roll,style(context,id));}
    static void bind(Context context,int id,String roll,String style){
        if(!CLASSIC.equals(style)&&!FROST.equals(style))throw new IllegalArgumentException("请选择有效的组件样式");
        if(!owned(context,id))throw new IllegalArgumentException("桌面组件不存在，请重新添加");
        if(!roll.isEmpty())try(LogStore logs=new LogStore(Workspace.context(Workspace.root(context)))){if(!available(logs.roll(roll)))throw new IllegalArgumentException("请选择仍可记录的拍摄中胶卷");}
        if(!Workspace.root(context).getSharedPreferences(PREFS,0).edit().putString(id+".workspace",Workspace.current(context)).putString(id+".roll",roll).putString(id+".style",style).commit())throw new IllegalStateException("无法保存桌面组件设置");
        update(context,id);
    }
    static void updateAll(Context context){AppWidgetManager manager=AppWidgetManager.getInstance(context);for(int id:manager.getAppWidgetIds(new ComponentName(context,ExposureWidget.class)))update(context,id);}
    static void update(Context context,int id){AppWidgetManager.getInstance(context).updateAppWidget(id,views(context,id));}
    static RemoteViews views(Context context,int id){return views(context,id,AppWidgetManager.getInstance(context).getAppWidgetOptions(id));}
    static RemoteViews views(Context context,int id,android.os.Bundle options){
        if(android.os.Build.VERSION.SDK_INT>=31){
            java.util.ArrayList<android.util.SizeF> sizes=options.getParcelableArrayList(AppWidgetManager.OPTION_APPWIDGET_SIZES);
            if(sizes!=null&&!sizes.isEmpty()&&sizes.size()<=16){java.util.Map<android.util.SizeF,RemoteViews> layouts=new java.util.LinkedHashMap<>();for(android.util.SizeF size:sizes)if(size!=null&&Float.isFinite(size.getWidth())&&Float.isFinite(size.getHeight())&&size.getWidth()>0&&size.getHeight()>0)layouts.put(size,views(context,id,Math.round(size.getWidth()),Math.round(size.getHeight())));if(!layouts.isEmpty())return new RemoteViews(layouts);}
        }
        int minWidth=Math.max(180,options.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,300)),minHeight=Math.max(110,options.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,180));
        int maxWidth=Math.max(minWidth,options.getInt(AppWidgetManager.OPTION_APPWIDGET_MAX_WIDTH,minWidth)),maxHeight=Math.max(minHeight,options.getInt(AppWidgetManager.OPTION_APPWIDGET_MAX_HEIGHT,minHeight));
        return new RemoteViews(views(context,id,maxWidth,minHeight),views(context,id,minWidth,maxHeight));
    }
    static RemoteViews views(Context context,int id,int width,int height){
        float scale=context.getResources().getConfiguration().fontScale;boolean narrow=width<280&&height>=360+Math.round(Math.max(0,scale-1)*100),compact=!narrow&&(width<280||height<230||(height<300&&scale>1.2f)),mini=compact&&(width<260||(height<130&&scale>1.5f));
        boolean frost=FROST.equals(style(context,id)),frostPortrait=width<280&&height>=320,frostMini=!frostPortrait&&(width<260||height<140);
        RemoteViews views=new RemoteViews(context.getPackageName(),frost?(frostPortrait?R.layout.exposure_widget_frost_narrow:frostMini?R.layout.exposure_widget_frost_mini:height>=230&&scale<=1.2f?R.layout.exposure_widget_frost_wide:R.layout.exposure_widget_frost):mini?R.layout.exposure_widget_mini:compact?R.layout.exposure_widget_compact:narrow?R.layout.exposure_widget_narrow:R.layout.exposure_widget);String rollId=target(context,id),title="胶片随记",detail="请选择拍摄中的胶卷",action="选择胶卷",badge="选择",count="—";boolean ready=false;int total=1,taken=0;
        if(!rollId.isEmpty())try(LogStore logs=new LogStore(Workspace.context(Workspace.root(context)))){LogStore.Roll roll=logs.roll(rollId);title=roll.stock;ready=available(roll);detail=(roll.iso>0?"ISO "+roll.iso:"ISO 未记")+(roll.camera.isEmpty()?"":" • "+roll.camera);total=roll.capacity;taken=roll.count;count=taken+"/"+total;boolean nominal=RecordRules.nominalReached(logs.nextFrame(rollId)-1,roll.capacity);if(ready&&nominal){CatalogStore.Detail metadata=new CatalogStore(logs).detail(rollId);detail=RecordRules.nominalWarning(roll.capacity,metadata==null?"":metadata.format);}badge=ready?(nominal?"留意余量":"拍摄中"):"已结束";action=ready?"记录第"+logs.nextFrame(rollId)+"张":"查看胶卷";
            if(!frost)views.setImageViewBitmap(R.id.widget_strip,WidgetCard.render(new HomeRollCard.ExposureWindows(context,taken,total),LibraryUi.dp(context,Math.max(1,Math.min(600,width))),LibraryUi.dp(context,24)));
            android.widget.ImageView logo=WidgetCard.logoView(context,WidgetCard.logo(context,logs,roll));if(frost)logo.setImageTintList(android.content.res.ColorStateList.valueOf(context.getColor(R.color.widget_frost_ink)));logo.setScaleType(android.widget.ImageView.ScaleType.FIT_START);android.graphics.Bitmap mark=WidgetCard.render(logo,LibraryUi.dp(context,frost?84:150),LibraryUi.dp(context,frost?16:24));views.setImageViewBitmap(R.id.widget_logo,mark);if(!frost&&mini)views.setImageViewBitmap(R.id.widget_logo_small,mark);
            views.setImageViewBitmap(R.id.widget_cover,WidgetCard.cover(context,logs,roll,Math.min(512,LibraryUi.dp(context,frost?(frostMini?24:(frostPortrait||height>=230&&scale<=1.2f)?48:36):mini?48:narrow?Math.max(48,width-24):Math.min(height-24,Math.max(40,width-180))))));if(frost){views.setTextViewText(R.id.widget_count,String.valueOf(taken));views.setTextViewText(R.id.widget_frost_total,"／"+total);}else{HomeRollCard.Fraction fraction=new HomeRollCard.Fraction(context,taken,total);fraction.measure(0,0);views.setImageViewBitmap(R.id.widget_count,WidgetCard.render(fraction,fraction.getMeasuredWidth(),fraction.getMeasuredHeight()));}views.setContentDescription(R.id.widget_count,count);
            CatalogStore.Detail d=new CatalogStore(logs).detail(roll.id);if(ready&&!nominal)detail=roll.camera+"\n"+(d==null?"":d.format+(d.halfFrame?" 半格":"")+" · ")+"ISO "+roll.iso;}catch(Exception missing){detail="胶卷暂不可用，请重新选择";rollId="";}
        if(!frost&&!narrow&&!mini)views.setInt(R.id.widget_cover,"setMaxWidth",LibraryUi.dp(context,Math.max(40,width-180)));
        if(!frost&&compact&&scale>1.2f)views.setViewVisibility(R.id.widget_empty_heading,android.view.View.GONE);
        if(!frost&&compact){views.setViewVisibility(R.id.widget_detail,height<130||scale>1.2f?android.view.View.GONE:android.view.View.VISIBLE);views.setContentDescription(R.id.widget_configure,"切换胶卷，"+title);}if(frost||!narrow)detail=detail.replace("\n"," · ");if(!frost&&mini){views.setInt(R.id.widget_title,"setMaxLines",height<150?1:2);views.setViewVisibility(R.id.widget_logo,android.view.View.GONE);views.setViewVisibility(R.id.widget_logo_small,android.view.View.VISIBLE);}
        views.setTextViewText(R.id.widget_title,title);views.setTextViewText(R.id.widget_detail,detail);views.setTextViewText(R.id.widget_action,ready?"记录":"查看");views.setContentDescription(R.id.widget_action,action);views.setContentDescription(R.id.widget_meter,"测光记录");views.setTextViewText(R.id.widget_meter,"测光");if(scale>1.2f){views.setTextViewText(R.id.widget_start,"新胶卷");views.setTextViewText(R.id.widget_empty_choose,"选胶卷");}views.setContentDescription(R.id.widget_start,"开始新胶卷");views.setContentDescription(R.id.widget_empty_choose,"选择已有胶卷");views.setContentDescription(R.id.widget_body,title+"，"+detail+"，"+count);views.setViewVisibility(R.id.widget_active,rollId.isEmpty()?android.view.View.GONE:android.view.View.VISIBLE);views.setViewVisibility(R.id.widget_empty,rollId.isEmpty()?android.view.View.VISIBLE:android.view.View.GONE);views.setViewVisibility(R.id.widget_meter,ready?android.view.View.VISIBLE:android.view.View.GONE);
        if(rollId.isEmpty()){String emptyText="没有拍摄中的胶卷";try(LogStore logs=new LogStore(Workspace.context(Workspace.root(context)))){for(LogStore.Roll candidate:logs.rolls())if(available(candidate)){emptyText="尚未选择拍摄中的胶卷";break;}}catch(Exception unavailable){emptyText="胶卷暂不可用，请重新选择";}views.setTextViewText(R.id.widget_empty_note,emptyText);}
        if(frost){if(height<150)views.setViewVisibility(R.id.widget_empty_heading,android.view.View.GONE);views.setTextViewText(R.id.widget_action,ready?(width>=300&&scale<=1.2f?"＋ "+action:"＋ 记录"):"查看");views.setContentDescription(R.id.widget_configure,"调整样式与胶卷，"+title);views.setViewVisibility(R.id.widget_detail,!frostPortrait&&(height<150&&scale>1.2f||frostMini)?android.view.View.GONE:android.view.View.VISIBLE);if(frostMini)views.setInt(R.id.widget_title,"setMaxLines",1);}
        Intent open=new Intent(context,MainActivity.class).setData(android.net.Uri.parse("filmlog-widget://open/"+id)).putExtra("widget_workspace",Workspace.current(context));if(!rollId.isEmpty())open.putExtra("open_roll",rollId).putExtra("open_editor",ready);
        PendingIntent entry=PendingIntent.getActivity(context,id,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Intent detailIntent=new Intent(open).setData(android.net.Uri.parse("filmlog-widget://detail/"+id)).putExtra("open_editor",false);PendingIntent homepage=PendingIntent.getActivity(context,id,detailIntent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);views.setOnClickPendingIntent(R.id.widget_body,homepage);views.setOnClickPendingIntent(R.id.widget_action,rollId.isEmpty()?PendingIntent.getActivity(context,id,new Intent(context,WidgetConfigureActivity.class).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id).setData(android.net.Uri.parse("filmlog-widget://choose/"+id)),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE):entry);
        Intent meter=new Intent(context,MainActivity.class).setData(android.net.Uri.parse("filmlog-widget://meter/"+id)).putExtra("widget_workspace",Workspace.current(context)).putExtra("open_roll",rollId).putExtra("widget_meter",true);views.setOnClickPendingIntent(R.id.widget_meter,PendingIntent.getActivity(context,id,meter,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));
        Intent configure=new Intent(context,WidgetConfigureActivity.class).setData(android.net.Uri.parse("filmlog-widget://configure/"+id)).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);views.setOnClickPendingIntent(R.id.widget_configure,homepage);views.setContentDescription(R.id.widget_configure,"查看胶卷，"+title);
        Intent create=new Intent(context,MainActivity.class).setData(android.net.Uri.parse("filmlog-widget://new/"+id)).putExtra("widget_workspace",Workspace.current(context)).putExtra("new_roll",true);PendingIntent newRoll=PendingIntent.getActivity(context,id,create,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);views.setOnClickPendingIntent(R.id.widget_empty,newRoll);views.setOnClickPendingIntent(R.id.widget_start,newRoll);views.setOnClickPendingIntent(R.id.widget_empty_choose,PendingIntent.getActivity(context,id,configure,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));
        return views;
    }
    @Override public void onAppWidgetOptionsChanged(Context c,AppWidgetManager manager,int id,android.os.Bundle options){manager.updateAppWidget(id,views(c,id,options));}
    @Override public void onUpdate(Context context,AppWidgetManager manager,int[] ids){for(int id:ids)update(context,id);}
    @Override public void onDeleted(Context context,int[] ids){SharedPreferences.Editor prefs=Workspace.root(context).getSharedPreferences(PREFS,0).edit();for(int id:ids)prefs.remove(id+".workspace").remove(id+".roll").remove(id+".style");prefs.apply();}
    @Override public void onRestored(Context context,int[] oldIds,int[] newIds){SharedPreferences prefs=Workspace.root(context).getSharedPreferences(PREFS,0);SharedPreferences.Editor edit=prefs.edit();for(int i=0;i<oldIds.length;i++){if(oldIds[i]==newIds[i])continue;edit.putString(newIds[i]+".workspace",prefs.getString(oldIds[i]+".workspace","")).putString(newIds[i]+".roll",prefs.getString(oldIds[i]+".roll","")).putString(newIds[i]+".style",prefs.getString(oldIds[i]+".style",CLASSIC)).remove(oldIds[i]+".workspace").remove(oldIds[i]+".roll").remove(oldIds[i]+".style");}edit.apply();for(int id:newIds)update(context,id);}
}
